window.kbPageData["views/entry/k-0ba792186ee1e494"] = {"key":"entry/k-0ba792186ee1e494","state":{"route":"entry/k-0ba792186ee1e494"},"node":{"id":"k-0ba792186ee1e494","mode":"k","title":"两期平均数比较","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["两期平均数的升降由分子与分母的增长率大小决定","正数比值在分子增速高于分母增速时上升","两期平均数的升降由总量增速与份数增速的大小关系决定","分子同比增速高于分母同比增速时平均数上升","分子增速高于分母增速时平均数上升"],"qs":["国考 2024 副省级 行测#123","江苏 2024 A类 行测#119","江苏 2024 B类 行测#119","江苏 2025 A类 行测#129","江苏 2025 C类 行测#129"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":5,"repeatPositions":0,"directorySummary":"当两期总量和对应的单位数均为正时，总量增速高于单位数增速，平均数上升；低于则下降，相等则持平。","review":{"definition":"当两期总量和对应的单位数均为正时，总量增速高于单位数增速，平均数上升；低于则下降，相等则持平。","explanation":"本题用减少个人垫付总额除以直接结算人次，得到每结算人次减少的垫付金额。本期平均数与上期平均数之比等于（1＋总额环比增速）÷（1＋人次环比增速）。门诊慢特病相关治疗费用的这两个增速分别为97.9%和89.5%，比值大于1。门诊费用整体、普通门诊和定点零售药店的总额增速分别为40.1%、36.8%和24.6%，均低于对应的人次增速47.6%、49.6%和39.0%，因此只有D项的平均金额环比增加。","references":[],"evidence":"当分子的增长率大于分母的增长率时，平均数上升","disposition":"独立词条","basis":"据原题和解析编释。","title":"两期平均数比较","related":[],"examFocus":{"国考 2024 副省级 行测#123":"判断马铃薯单位面积产量的同比变化，可逐年比较总产量和播种面积的同比增速。","江苏 2024 A类 行测#119":"判断人均减少垫付金额的环比变化，要在同一结算类别内比较减少个人垫付总额与直接结算人次的环比增速。","江苏 2024 B类 行测#119":"判断人均减少垫付金额的环比变化，要在同一结算类别内比较减少个人垫付总额与直接结算人次的环比增速。","江苏 2025 A类 行测#129":"判断柴油机和汽油机的进出口均价变化，要按产品和进出口方向分别比较金额与台数的同比增速。","江苏 2025 C类 行测#129":"判断柴油机和汽油机的进出口均价变化，要按产品和进出口方向分别比较金额与台数的同比增速。"}},"readings":[{"origin":"k-0ba792186ee1e494","title":"两期平均数比较","qs":["江苏 2024 A类 行测#119"],"definition":"当两期总量和对应的单位数均为正时，总量增速高于单位数增速，平均数上升；低于则下降，相等则持平。","explanation":"本题用减少个人垫付总额除以直接结算人次，得到每结算人次减少的垫付金额。本期平均数与上期平均数之比等于（1＋总额环比增速）÷（1＋人次环比增速）。门诊慢特病相关治疗费用的这两个增速分别为97.9%和89.5%，比值大于1。门诊费用整体、普通门诊和定点零售药店的总额增速分别为40.1%、36.8%和24.6%，均低于对应的人次增速47.6%、49.6%和39.0%，因此只有D项的平均金额环比增加。","evidence":"当分子的增长率大于分母的增长率时，平均数上升","doubt":"","references":[]},{"origin":"k-1b47eb7ebcaae46d","title":"两期平均数比较","qs":["国考 2024 副省级 行测#123"],"definition":"当两期的分子和分母均为正数时，分子增速高于分母增速，比值上升。两者增速相等时，比值不变。分子增速低于分母增速时，比值下降。","explanation":"本年比值是上年比值的（1＋分子同比增速）÷（1＋分母同比增速）倍，所以只需比较两个增速。马铃薯单位面积产量等于总产量除以播种面积。2018、2020、2021、2022年总产量上升、播种面积下降，单产均增长。2019年总产量从1798万吨降至1778万吨，降约1.11%，播种面积从476万公顷降至467万公顷，降约1.89%，总产量的降幅较小，单产仍然增长。2018至2022年共有5年同比增长，选D。","evidence":"当分子增速（a）大于分母增速（b）时，平均数上升","doubt":"","references":[]},{"origin":"k-3187824e10525ab3","title":"两期平均数比较","qs":["江苏 2024 B类 行测#119"],"definition":"平均数等于总量除以份数。两期的总量与份数均为正且统计口径一致时，总量增速大于份数增速，平均数上升。两者相等时平均数持平，总量增速较小时平均数下降。","explanation":"本期平均数与上期平均数之比，等于（1＋总量增速）除以（1＋份数增速）。第119题以减少个人垫付总额为分子、直接结算人次为分母。门诊慢特病的垫付减少额环比增长97.9%，高于结算人次的89.5%。其余三项的金额增速均低于各自的人次增速，因此只有D项的人均减少垫付金额环比上升。","evidence":"当分子的增长率大于分母的增长率时，平均数上升","doubt":"","references":[]},{"origin":"k-8eb0b848f0555462","title":"两期平均数比较","qs":["江苏 2025 C类 行测#129"],"definition":"对于用总量除以数量得到的平均数，在两期总量和数量均为正、统计口径一致的条件下，总量同比增速高于数量同比增速时，平均数上升。两者增速相等时，平均数持平。总量同比增速较低时，平均数下降。","explanation":"本期平均数与上年平均数之比，等于（1＋总量同比增速）÷（1＋数量同比增速）。第129题以进出口金额为总量、对应的进出口台数为数量。柴油机出口和进口的金额增速分别为18.9%和41.7%，均高于对应的数量增速10.0%和7.3%，所以两项均价均上涨。汽油机出口金额增速3.4%低于数量增速6.3%，进口金额增速−28.5%也低于数量增速−28.2%，所以两项均价均下降，选D。","evidence":"分子增长率（a）>分母增长率（b），平均数上升","doubt":"","references":[]},{"origin":"k-f350778522a2f507","title":"两期平均数比较","qs":["江苏 2025 A类 行测#129"],"definition":"平均数等于总量除以对应的数量。当基期总量和两期数量均为正时，总量增速高于数量增速，平均数上升；两者相等，平均数持平；总量增速低于数量增速，平均数下降。","explanation":"本期平均数是基期平均数的（1＋总量增速）÷（1＋数量增速）倍。本题以进出口金额为总量、台数为数量，分别比较同一产品、同一进出口方向下的两个增速。柴油机出口的金额增速18.9%高于数量增速10.0%，进口的金额增速41.7%也高于数量增速7.3%，所以两项平均价格均上涨。汽油机出口的3.4%低于6.3%，进口的−28.5%低于−28.2%，两项平均价格均下降，故选D。","evidence":"分子增长率（a）>分母增长率（b），平均数上升","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#123":{"paper":"国考 2024 副省级 行测","n":123,"mod":"资料分析","src":["a566fec37e508ca7f975.pdf",25],"asrc":["a475ecf57d968bc14cd6.pdf",39],"card":"ff6e0ac172a4be3fe00b3740","links":[{"id":"k-0ba792186ee1e494","role":"解题依据","why":"比较产量和播种面积的同比增速即可判定单产变化方向。"}]},"江苏 2024 A类 行测#119":{"paper":"江苏 2024 A类 行测","n":119,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",24],"asrc":["0126a1c8aceee632ea2b.pdf",37],"card":"3e6463fae191b7b8b7be27ec","links":[{"id":"k-0ba792186ee1e494","role":"解题依据","why":"在本题的正值口径下，总额增速高于人次增速时，单位人次平均金额才会上升。"}]},"江苏 2024 B类 行测#119":{"paper":"江苏 2024 B类 行测","n":119,"mod":"资料分析","src":["0ae7ac475476e5635bd7.pdf",23],"asrc":["8dd171daee6fc74e9718.pdf",40],"card":"1bd16993e34eff5e919339dc","links":[{"id":"k-0ba792186ee1e494","role":"直接考查","why":"判断人均减少垫付金额是否上升，取决于减少垫付总额的环比增速是否高于结算人次的环比增速。"}]},"江苏 2025 A类 行测#129":{"paper":"江苏 2025 A类 行测","n":129,"mod":"资料分析","src":["98687766ac277f427cd6.pdf",27],"asrc":["4fe8e0544dd7b47699d2.pdf",42],"card":"31a8c5af4c8f8d55ce942efc","links":[{"id":"k-0ba792186ee1e494","role":"解题依据","why":"金额增速与数量增速的相对大小决定平均价格的变化方向。"}]},"江苏 2025 C类 行测#129":{"paper":"江苏 2025 C类 行测","n":129,"mod":"资料分析","src":["ffc394a1c160f331ec57.pdf",27],"asrc":["d1de3b437151c05b769e.pdf",38],"card":"665fd95ea84b33ebfc6aa101","links":[{"id":"k-0ba792186ee1e494","role":"解题依据","why":"平均价格以金额为分子、数量为分母，两者增速的大小关系决定均价变动方向。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-0ba792186ee1e494":[["国考 2024 副省级 行测#123"],["江苏 2024 A类 行测#119"],["江苏 2024 B类 行测#119"],["江苏 2025 A类 行测#129"],["江苏 2025 C类 行测#129"]]}};
